  "content": "Google은 관리 콘솔에서 Gemini Notebook의 사용·데이터 접근을 확인하는 감사 로그를 제공한다고 밝혔습니다. 노트북 공개 범위, 사용자·IP·리소스 맥락 등을 확인할 수 있으며 BigQuery 등으로 내보내 검토할 수 있습니다.\n\n관리 콘솔에서는 기본으로 제공되지만 BigQuery 내보내기는 관리자가 켜야 합니다. 9월 3일부터 최대 15일에 걸쳐 순차 배포되며, 노트북·소스·채팅 기록 자체는 전 세계에 저장되어 데이터 지역 지정은 아직 지원하지 않습니다.\n\n날짜 안내: 2026-09-03는 발행자가 표시한 게시 날짜입니다. 게시 시각과 시간대가 확인되지 않아 한국시간으로 환산하거나 임의의 시각을 넣지 않았습니다.",
