  "title": "Google Pics, Workspace 이미지 생성·편집 정식 제공",
  "summary": "Google은 텍스트로 이미지를 만들고 개별 대상이나 글자를 선택해 편집하는 Pics의 정식 제공을 발표했습니다. Docs·Slides 연동, 2K·4K 업스케일, 버전 이력을 지원하며 요금제와 배포 일정에 따라 접근이 다릅니다.",
  "content": "Google은 텍스트로 이미지를 만들고 개별 대상이나 글자를 선택해 편집하는 Pics의 정식 제공을 발표했습니다. Docs·Slides 연동, 2K·4K 업스케일, 버전 이력을 지원하며 요금제와 배포 일정에 따라 접근이 다릅니다.\n\n빠른 출시 도메인은 9월 1일, 예약 출시 도메인은 9월 15일부터 최대 15일에 걸쳐 배포됩니다. Drive에 저장된 거의 모든 이미지를 한 번에 열어 편집하는 기능은 향후 몇 주 안의 계획으로 별도 안내했습니다.\n\n날짜 안내: 2026-09-01는 발행자가 표시한 게시 날짜입니다. 게시 시각과 시간대가 확인되지 않아 한국시간으로 환산하거나 임의의 시각을 넣지 않았습니다.",
  "en": {
    "title": "Google Pics launches image creation and editing in Workspace",
    "summary": "Google announces general availability of Pics for prompt-based creation and object/text editing, with Docs/Slides integration, 2K/4K upscaling and version history. Access depends on plan and rollout schedule.",
    "content": "Google announces general availability of Pics for prompt-based creation and object/text editing, with Docs/Slides integration, 2K/4K upscaling and version history. Access depends on plan and rollout schedule.\n\nRapid Release rollout starts September 1 and Scheduled Release starts September 15, each taking up to 15 days. One-click editing of nearly any image saved in Drive is described separately as coming in the following weeks.\n\nDate disclosure: 2026-09-01 is the publisher-displayed publication date. No publication time or timezone was established, so it has not been converted to Korea time or assigned an invented time."
  },
  "source": "https://workspaceupdates.googleblog.com/2026/09/google-pics-brings-pro-level-ai-image-creation-and-editing-to-Google-Workspace.html",
  "officialUrl": "https://workspaceupdates.googleblog.com/2026/09/google-pics-brings-pro-level-ai-image-creation-and-editing-to-Google-Workspace.html",
