  "title": "Google Agent Platform, IAM 통합 접근 정책 정식 제공",
  "summary": "Google은 에이전트와 도구·다른 에이전트·엔드포인트 간 통신을 관리하는 IAM Unified Access Policies를 정식 제공한다고 밝혔습니다. 허용·거부 규칙, 도구명·HTTP 메서드 조건, 시험 평가와 실제 차단 모드를 지원합니다.",
  "content": "Google은 에이전트와 도구·다른 에이전트·엔드포인트 간 통신을 관리하는 IAM Unified Access Policies를 정식 제공한다고 밝혔습니다. 허용·거부 규칙, 도구명·HTTP 메서드 조건, 시험 평가와 실제 차단 모드를 지원합니다.\n\n날짜 안내: 2026-08-31는 발행자가 표시한 게시 날짜입니다. 게시 시각과 시간대가 확인되지 않아 한국시간으로 환산하거나 임의의 시각을 넣지 않았습니다.",
  "en": {
    "title": "Google makes unified agent access policies generally available",
    "summary": "Google says IAM Unified Access Policies are GA for agent communication with tools, other agents and endpoints. Features include allow/deny rules, conditions based on tool names and HTTP methods, and dry-run versus enforcement modes.",
    "content": "Google says IAM Unified Access Policies are GA for agent communication with tools, other agents and endpoints. Features include allow/deny rules, conditions based on tool names and HTTP methods, and dry-run versus enforcement modes.\n\nDate disclosure: 2026-08-31 is the publisher-displayed publication date. No publication time or timezone was established, so it has not been converted to Korea time or assigned an invented time."
  },
