  "content": "GitHub은 기업 관리 설정에서 Copilot 새 대화의 기본 모델을 지정하는 기능을 발표했습니다. 팀별 설정 파일과 재정의 옵션을 사용하면 팀마다 다른 기본 모델을 적용할 수 있습니다. Business·Enterprise의 지원 클라이언트에 제공됩니다.\n\nmodel 키를 재정의 가능 상태로 두고 team-mappings.json에 팀별 설정을 연결합니다. 별도 팀 설정이 없는 사용자는 기업 기본값을 따릅니다.\n\n표시 시각은 공식 피드 또는 릴리스의 게시 시각을 한국시간으로 환산한 값이며, 기능의 실제 활성화 시각과는 다를 수 있습니다.",
