  "summary": "Codex 릴리스 노트에 따르면 0.153.1은 Astra를 API 설정으로 지원했고, 0.153.3은 Amazon Bedrock 모델 목록에 추가했습니다. 0.153.4에서는 기본 제공 모델 선택기에 표시하고 명시적 설정이 없을 때 기본값으로 지정했습니다. 0.153.2의 Fast 배율 수정은 표시 문구 변경일 뿐 요청 실행 방식 변경은 아닙니다.",
  "content": "Codex 릴리스 노트에 따르면 0.153.1은 Astra를 API 설정으로 지원했고, 0.153.3은 Amazon Bedrock 모델 목록에 추가했습니다. 0.153.4에서는 기본 제공 모델 선택기에 표시하고 명시적 설정이 없을 때 기본값으로 지정했습니다. 0.153.2의 Fast 배율 수정은 표시 문구 변경일 뿐 요청 실행 방식 변경은 아닙니다.\n\n표시 시각은 공식 피드 또는 릴리스의 게시 시각을 한국시간으로 환산한 값이며, 실제 기능 활성화 시각과 다를 수 있습니다. 기능·성능·보안 설명은 출처가 발표한 내용이며 독립 실행 검증은 아닙니다.\n\n카드 시각은 통합한 네 개 패치 중 마지막 버전인 0.153.4 게시 시각입니다. 0.153.1·2는 한국시간 9월 4일, 0.153.3·4는 9월 5일에 게시됐습니다.",
  "source": "https://github.com/openai/codex/releases/tag/rust-v0.153.4",
