  "platform": "Web",
  "title": "OpenAI API, 급격한 트래픽과 모델 과부하 오류 구분",
  "summary": "OpenAI는 트래픽 증가가 너무 빠를 때 429 slow_down, 일시적인 모델 과부하에는 503 server_is_overloaded를 반환하도록 오류를 구분했다고 밝혔습니다. Retry-After가 있으면 그 시간을 기다리고, 없으면 지수 백오프를 사용하도록 안내합니다.",
  "content": "OpenAI는 트래픽 증가가 너무 빠를 때 429 slow_down, 일시적인 모델 과부하에는 503 server_is_overloaded를 반환하도록 오류를 구분했다고 밝혔습니다. Retry-After가 있으면 그 시간을 기다리고, 없으면 지수 백오프를 사용하도록 안내합니다.\n\n날짜 안내: 2026-09-02는 발행자가 표시한 게시 날짜입니다. 게시 시각과 시간대가 확인되지 않아 한국시간으로 환산하거나 임의의 시각을 넣지 않았습니다.",
  "en": {
    "title": "OpenAI distinguishes traffic ramp-up from model overload",
    "summary": "OpenAI says overly rapid traffic growth can return 429 slow_down, while temporary model overload returns 503 server_is_overloaded. Applications should honor Retry-After when present and otherwise use exponential backoff.",
    "content": "OpenAI says overly rapid traffic growth can return 429 slow_down, while temporary model overload returns 503 server_is_overloaded. Applications should honor Retry-After when present and otherwise use exponential backoff.\n\nDate disclosure: 2026-09-02 is the publisher-displayed publication date. No publication time or timezone was established, so it has not been converted to Korea time or assigned an invented time."
  },
