  "title": "ChatGPT iOS, 연결 호스트 첨부와 작업 우선순위 보기 추가",
  "summary": "OpenAI는 iOS 1.2026.237에서 Windows·Linux를 포함한 연결 호스트의 첨부, 사진 보관함 동영상, 작업 우선순위 보기를 추가했다고 밝혔습니다. 대기 프롬프트는 연결 호스트와 동기화되고 백그라운드에서도 전송됩니다.",
  "content": "OpenAI는 iOS 1.2026.237에서 Windows·Linux를 포함한 연결 호스트의 첨부, 사진 보관함 동영상, 작업 우선순위 보기를 추가했다고 밝혔습니다. 대기 프롬프트는 연결 호스트와 동기화되고 백그라운드에서도 전송됩니다.\n\n작업 목록과 연결 복구도 함께 손봤습니다. 긴 응답을 표시할 때의 끊김을 줄이고, 연결이 끊긴 뒤에도 사이드 채팅을 닫기 전까지 메시지를 유지하도록 했습니다.\n\n날짜 안내: 2026-09-01는 발행자가 표시한 게시 날짜입니다. 게시 시각과 시간대가 확인되지 않아 한국시간으로 환산하거나 임의의 시각을 넣지 않았습니다.",
  "en": {
    "title": "ChatGPT iOS adds connected-host attachments and Priority view",
    "summary": "OpenAI says version 1.2026.237 supports attachments across connected hosts, including Windows and Linux, plus Photo Library videos and a Priority task view. Queued prompts sync with the connected host and can send in the background.",
    "content": "OpenAI says version 1.2026.237 supports attachments across connected hosts, including Windows and Linux, plus Photo Library videos and a Priority task view. Queued prompts sync with the connected host and can send in the background.\n\nThe release also improves task-list loading and reconnect reliability, reduces interruptions while streaming long responses, and retains side-chat messages until the chat is closed.\n\nDate disclosure: 2026-09-01 is the publisher-displayed publication date. No publication time or timezone was established, so it has not been converted to Korea time or assigned an invented time."
  },
