  "summary": "Anthropic은 Claude가 11일 동안 주로 자율적으로 작업해 Lean 언어로 페르마의 마지막 정리의 기계 검증 가능한 증명을 작성했다고 밝혔습니다. 기존 정리를 새로 발견했다는 뜻이 아니라 증명을 컴퓨터로 검증할 수 있게 형식화한 연구입니다.",
  "content": "Anthropic은 Claude가 11일 동안 주로 자율적으로 작업해 Lean 언어로 페르마의 마지막 정리의 기계 검증 가능한 증명을 작성했다고 밝혔습니다. 기존 정리를 새로 발견했다는 뜻이 아니라 증명을 컴퓨터로 검증할 수 있게 형식화한 연구입니다.\n\nAnthropic은 결과물을 수학계의 기존 형식화 작업과 연결해 설명했습니다. 기사에 제시된 작업 기간과 성과는 회사의 보고이며, 이번 정리는 기존 수학 증명을 컴퓨터로 검사할 수 있는 형태로 옮긴 작업입니다.\n\n날짜 안내: 2026-09-04는 발행자가 표시한 게시 날짜입니다. 게시 시각과 시간대가 확인되지 않아 한국시간으로 환산하거나 임의의 시각을 넣지 않았습니다.",
  "en": {
    "title": "Anthropic reports a computer-checked formalization of Fermat’s Last Theorem",
    "summary": "Anthropic says Claude worked largely autonomously for 11 days to produce a Lean proof of Fermat’s Last Theorem. This is formalization of an established theorem for computer checking, not discovery of the theorem.",
    "content": "Anthropic says Claude worked largely autonomously for 11 days to produce a Lean proof of Fermat’s Last Theorem. This is formalization of an established theorem for computer checking, not discovery of the theorem.\n\nAnthropic places the result alongside existing mathematical formalization efforts. The reported duration and achievement are the company’s account; the work translates an established mathematical proof into a computer-checkable form.\n\nDate disclosure: 2026-09-04 is the publisher-displayed publication date. No publication time or timezone was established, so it has not been converted to Korea time or assigned an invented time."
  },
