      "title": "Cohere, 에이전트 도구가 실제 어떤 일을 하는지 분석",
      "summary": "Cohere는 공개 도구 디렉터리 7개를 모은 Agentic Task Ecosystem 데이터셋과 분석을 공개했습니다. 약 69만 6천 도구 가운데 직업 과업을 직접 수행한다는 엄격한 기준을 충족한 비율은 2.6%라고 보고했습니다. 이 수치를 전체 일자리의 자동화 비율로 해석해서는 안 됩니다.",
      "content": "Cohere는 공개 도구 디렉터리 7개를 모은 Agentic Task Ecosystem 데이터셋과 분석을 공개했습니다. 약 69만 6천 도구 가운데 직업 과업을 직접 수행한다는 엄격한 기준을 충족한 비율은 2.6%라고 보고했습니다. 이 수치를 전체 일자리의 자동화 비율로 해석해서는 안 됩니다.\n\n데이터는 약 12만 3천 개 MCP 서버를 포함합니다. 도구의 존재와 직업 전체의 대체는 구분해야 하며, 연구는 어떤 업무가 소프트웨어로 실행 가능한 형태로 구현되고 있는지를 분석합니다.\n\n날짜 안내: 2026-09-03는 발행자가 표시한 게시 날짜입니다. 게시 시각과 시간대가 확인되지 않아 한국시간으로 환산하거나 임의의 시각을 넣지 않았습니다.",
