      "deck": "Vercel이 @ai-sdk/harness-fx를 추가했습니다.",
      "summary": "Vercel이 @ai-sdk/harness-fx를 추가했습니다. 공개 코딩 에이전트 fx를 ACP 연결로 실행하며 다른 지원 에이전트와 같은 HarnessAgent 인터페이스를 사용합니다.",
      "content": "Vercel이 @ai-sdk/harness-fx를 추가했습니다. 공개 코딩 에이전트 fx를 ACP 연결로 실행하며 다른 지원 에이전트와 같은 HarnessAgent 인터페이스를 사용합니다.\n\n원문에 표시된 게시 날짜를 유지했으며 정확한 공개 시각은 확정하지 않았습니다.\n\n표시 날짜는 발행자의 게시일입니다. 시간대가 확정되지 않은 날짜를 한국시간으로 환산하거나 임의의 시각을 넣지 않았습니다.",
