      "title": "Vercel AI Gateway, 사용자별 지출 한도 제공",
      "deck": "Vercel AI Gateway에서 팀 사용자별 지출 한도를 설정할 수 있습니다.",
      "summary": "Vercel AI Gateway에서 팀 사용자별 지출 한도를 설정할 수 있습니다. 사용자에게 귀속된 API 키와 앱 토큰의 비용을 합산하며 한도 도달 시 새 요청을 거절합니다. 기존 키는 호환성을 위해 팀에 귀속되므로 사용자별 한도를 적용하려면 키 귀속을 확인해야 합니다.",
      "content": "Vercel AI Gateway에서 팀 사용자별 지출 한도를 설정할 수 있습니다. 사용자에게 귀속된 API 키와 앱 토큰의 비용을 합산하며 한도 도달 시 새 요청을 거절합니다. 기존 키는 호환성을 위해 팀에 귀속되므로 사용자별 한도를 적용하려면 키 귀속을 확인해야 합니다.\n\n원문에 표시된 게시 날짜를 유지했으며 정확한 공개 시각은 확정하지 않았습니다.\n\n표시 날짜는 발행자의 게시일입니다. 시간대가 확정되지 않은 날짜를 한국시간으로 환산하거나 임의의 시각을 넣지 않았습니다.",
      "source": "https://vercel.com/changelog/set-per-user-budgets-on-ai-gateway",
