      "deck": "Vercel이 Sandbox 스냅샷 저장 요금을 월 전체 평균 대신 일별 평균 사용량으로 계산하도록 변경했습니다.",
      "summary": "Vercel이 Sandbox 스냅샷 저장 요금을 월 전체 평균 대신 일별 평균 사용량으로 계산하도록 변경했습니다. 단가는 GB·월당 0.08달러로 유지되며 Pro·Enterprise의 다음 청구 기간부터 자동 적용됩니다.",
      "content": "Vercel이 Sandbox 스냅샷 저장 요금을 월 전체 평균 대신 일별 평균 사용량으로 계산하도록 변경했습니다. 단가는 GB·월당 0.08달러로 유지되며 Pro·Enterprise의 다음 청구 기간부터 자동 적용됩니다.\n\n원문에 표시된 게시 날짜를 유지했으며 정확한 공개 시각은 확정하지 않았습니다.\n\n표시 날짜는 발행자의 게시일입니다. 시간대가 확정되지 않은 날짜를 한국시간으로 환산하거나 임의의 시각을 넣지 않았습니다.",
